package com.aistock.notification.alert;
import com.aistock.common.BusinessException;
import com.fasterxml.jackson.databind.*;
import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class AlertMarketUseClientTest {
 final ObjectMapper m=new ObjectMapper();final String op=UUID.randomUUID().toString(),requestId=UUID.randomUUID().toString(),raw=UUID.randomUUID().toString(),bundle=UUID.randomUUID().toString(),use=UUID.randomUUID().toString();
 HttpServer server;String response;int status=200;AtomicInteger calls=new AtomicInteger();String path,body;
 AlertMarketUseClient.Request request(){return new AlertMarketUseClient.Request(op,"1",requestId,raw);}
 String receipt(String id,String state)throws Exception{var n=m.createObjectNode().put("protocolVersion","market-version-use-v1").put("bundleId",bundle).put("owner","notification").put("purpose","ALERT_EVALUATION").put("ownerOperationId",op).put("generation","1").put("state",state);if(id==null)n.putNull("requestId");else n.put("requestId",id);n.putArray("versionIds").add(raw);n.putArray("uses").addObject().put("useId",use).put("versionId",raw).put("lifecycleRevision","0");return m.createObjectNode().put("code","OK").set("data",n).toString();}
 @BeforeEach void setup()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();assertEquals("private",e.getRequestHeaders().getFirst("X-Service-Token"));path=e.getRequestURI().toString();body=new String(e.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);e.sendResponseHeaders(status,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();}
 @AfterEach void close(){server.stop(0);}
 AlertMarketUseClient client(){return new AlertMarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",Duration.ofSeconds(1));}
 @Test void readinessRequiresActualEvidenceGateAndProtocol(){response="{\"code\":\"OK\",\"data\":{\"protocolVersion\":\"market-version-use-v1\",\"protocolEnabled\":true,\"evidenceGatesEnabled\":false}}";assertThrows(BusinessException.class,()->client().requireReady());response=response.replace("false","true");assertDoesNotThrow(()->client().requireReady());assertEquals("/internal/v1/market-version-uses/capabilities",path);}
 @Test void registerAndLookupBindExactIdentityAndManifest()throws Exception{response=receipt(requestId,"ACTIVE");var c=client();assertEquals(List.of(raw),c.register(request()).versionIds());var sent=m.readTree(body);assertEquals(requestId,sent.path("requestId").asText());assertEquals(raw,sent.path("selector").path("versionIds").get(0).asText());assertEquals(bundle,c.find(request()).orElseThrow().bundleId());assertTrue(path.startsWith("/internal/v1/market-version-uses/requests/"+requestId+"?"));response=response.replace(raw,UUID.randomUUID().toString());assertThrows(BusinessException.class,()->c.find(request()));}
 @Test void malformedDuplicateRedirectAndOversizedResponsesAreRejected()throws Exception{var c=client();response=receipt(requestId,"ACTIVE").replace("\"generation\":\"1\"","\"generation\":\"1\",\"generation\":\"2\"");assertThrows(BusinessException.class,()->c.register(request()));response=receipt(requestId,"ACTIVE");status=302;assertThrows(BusinessException.class,()->c.register(request()));status=200;response="x".repeat(65537);assertThrows(BusinessException.class,()->c.register(request()));}
 @Test void completionOnlySendsIdentityAndRequiresReleasedReceipt()throws Exception{var c=client();response=receipt(null,"RELEASED");var r=new AlertMarketUseClient.Receipt(bundle,"ACTIVE",List.of(raw));assertEquals("RELEASED",c.complete(request(),r).state());assertEquals(Set.of("owner","purpose","ownerOperationId","generation"),m.convertValue(m.readTree(body),Map.class).keySet());response=receipt(null,"ACTIVE");assertThrows(BusinessException.class,()->c.complete(request(),r));}
 @Test void missingLookupIsNotPermissionToRegisterAgain(){response="{\"code\":\"MARKET_VERSION_RESOURCE_NOT_FOUND\",\"data\":null}";status=404;assertTrue(client().find(request()).isEmpty());assertEquals(1,calls.get());}
 @Test void invalidConfigurationAndMissingTokenDoNotSend(){response="{}";assertThrows(IllegalArgumentException.class,()->new AlertMarketUseClient("http://x/path","private",Duration.ofSeconds(1)));assertThrows(IllegalArgumentException.class,()->new AlertMarketUseClient("http://x","private",Duration.ofSeconds(5)));assertThrows(BusinessException.class,()->new AlertMarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"",Duration.ofSeconds(1)).requireReady());assertEquals(0,calls.get());}

 @Test void entireBodyHasDeadlineEvenAfterHeadersArrive()throws Exception{server.removeContext("/");var finish=new java.util.concurrent.CountDownLatch(1);server.createContext("/",e->{try{e.sendResponseHeaders(200,100);e.getResponseBody().write('{');e.getResponseBody().flush();finish.await(2,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception ignored){}finally{e.close();}});var c=new AlertMarketUseClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",Duration.ofMillis(150));try{assertTimeoutPreemptively(Duration.ofSeconds(1),()->assertThrows(BusinessException.class,c::requireReady));}finally{finish.countDown();}}

}
